// Add per-stage timing with request correlation in Node.js HTTP handler
function handleRequest(req, res) {
  const requestId = req.headers['x-request-id'] ?? generateId();
  const startTime = process.hrtime.bigint();

  // HTTP processing timer
  const httpStart = process.hrtime.bigint();
  // ... request parsing and validation
  const httpDuration = Number(process.hrtime.bigint() - httpStart) / 1000000;

  // Database operation timer
  const dbStart = process.hrtime.bigint();
  await database.save(data);
  const dbDuration = Number(process.hrtime.bigint() - dbStart) / 1000000;

  // Kafka publishing timer
  const kafkaStart = process.hrtime.bigint();
  await kafkaProducer.send(event);
  const kafkaDuration = Number(process.hrtime.bigint() - kafkaStart) / 1000000;

  // Log metrics with request correlation
  metrics.record('http_latency', httpDuration, { requestId });
  metrics.record('db_latency', dbDuration, { requestId });
  metrics.record('kafka_latency', kafkaDuration, { requestId });
}
```

