// Simple in-process LRU cache for flags
class FlagCache {
  constructor(ttlMs) { this.ttl=ttlMs; this.map=new Map(); }
  get(k){ const v=this.map.get(k); if(!v) return null; if(Date.now()-v.ts>this.ttl) { this.map.delete(k); return null; } return v.val; }
  set(k,v){ this.map.set(k,{val:v,ts:Date.now()}); }
}
```

